-- Admin-manageable 'Meet the Team' section: name, role/title, and an
-- uploaded photo per person, ordered via display_order. Photo storage
-- mirrors exhibitions.image (MEDIUMTEXT holding a data: URL, served through
-- a dedicated /api/team-members/[id]/photo route) so list responses stay
-- small instead of shipping every headshot's base64 on every fetch.
CREATE TABLE IF NOT EXISTS team_members (
  id INT AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(191) NOT NULL,
  role VARCHAR(191) NOT NULL,
  photo MEDIUMTEXT,
  display_order INT NOT NULL DEFAULT 0,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);

INSERT INTO team_members (name, role, photo, display_order)
SELECT * FROM (SELECT
  'Vishal Saini' AS name, 'Founder' AS role, 'data:image/jpeg;base64,' AS photo, 1 AS display_order
UNION ALL SELECT
  'Tahir Ghuman' AS name, 'CEO' AS role, 'data:image/jpeg;base64,' AS photo, 2 AS display_order
UNION ALL SELECT
  'Anastasia Ponomareva' AS name, 'Managing Director' AS role, 'data:image/jpeg;base64,' AS photo, 3 AS display_order
UNION ALL SELECT
  'Derek Usman' AS name, 'Director' AS role, 'data:image/jpeg;base64,' AS photo, 4 AS display_order
) AS seed
WHERE NOT EXISTS (SELECT 1 FROM team_members);
